import React, { useEffect, useState } from 'react';
import { obtenerEntidades, crearTarea } from '../services/api';

export default function TareaForm({ onTareaCreada, toast }) {
  const [entidades, setEntidades] = useState([]);
  const [entidadId, setEntidadId] = useState('');
  const [descripcion, setDescripcion] = useState('');

  useEffect(() => {
    obtenerEntidades().then(setEntidades);
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await crearTarea({ entidadMunicipalId: parseInt(entidadId), descripcion });
      toast.success("Tarea agregada correctamente");
      setEntidadId('');
      setDescripcion('');
      onTareaCreada();
    } catch (error) {
      toast.error("Hubo un error al agregar la tarea");
    }

    if (!entidadId || !descripcion.trim()) {
      toast.error("Por favor completa todos los campos");
      return;
    }

    const entidadSeleccionada = entidades.find(e => e.id_dependencia === parseInt(entidadId));

    await crearTarea({
    entidadMunicipalId: parseInt(entidadId),
    entidadMunicipalNombre: entidadSeleccionada.entidad_dependencia,
    descripcion,
    });

    setEntidadId('');
    setDescripcion('');
    onTareaCreada();
  };

  return (
    <form onSubmit={handleSubmit} className="p-4 border rounded mb-4 bg-white shadow-sm w-full">
      <label className="block mb-2">Entidad Municipal</label>
      <select
        value={entidadId}
        onChange={(e) => setEntidadId(e.target.value)}
        className="w-full p-2 mb-4 border rounded"
      >
        <option value="">-- Selecciona una entidad --</option>
        {entidades.map((entidad) => (
          <option key={entidad.id_dependencia} value={entidad.id_dependencia}>
            {entidad.entidad_dependencia}
          </option>
        ))}
      </select>

      <label className="block mb-2">Descripción de la tarea</label>
      <textarea
        value={descripcion}
        onChange={(e) => setDescripcion(e.target.value)}
        className="w-full p-2 mb-4 border rounded"
        rows="4"
      ></textarea>

      <button
        type="submit"
        disabled={!entidadId || !descripcion.trim()}
        className="bg-blue-500 text-white w-full sm:w-auto px-4 py-2 rounded"
      >
        Agregar Tarea
      </button>



    </form>
  );
}
